CREATE TABLE branch_msgs( branch_id TEXT, pos INTEGER, role TEXT, content_hash TEXT, chain_hash TEXT, PRIMARY KEY(branch_id, pos));
CREATE TABLE branches( branch_id TEXT PRIMARY KEY, session_id TEXT, parent_branch TEXT, forked_at INTEGER, status TEXT DEFAULT 'live', head_turn INTEGER DEFAULT -1);
CREATE TABLE caps( base_url TEXT, model TEXT, rung INTEGER, probed_at REAL, failures INTEGER DEFAULT 0, native TEXT DEFAULT '', anyof INTEGER DEFAULT -1, PRIMARY KEY(base_url, model));
CREATE TABLE checkpoints( branch_id TEXT, turn_index INTEGER, state TEXT, PRIMARY KEY(branch_id, turn_index));
CREATE TABLE director( id INTEGER PRIMARY KEY AUTOINCREMENT, branch_id TEXT, turn_index INTEGER, beat_id TEXT, scene_index INTEGER, ts REAL);
CREATE TABLE discovery( branch_id TEXT, name TEXT, turns TEXT DEFAULT '[]', status TEXT DEFAULT 'counting', PRIMARY KEY(branch_id, name));
CREATE TABLE effect_receipts( branch_id TEXT, effect_id TEXT, turn_index INTEGER, family TEXT, target TEXT, direction TEXT, delta INTEGER, payload_hash TEXT, owner TEXT, source TEXT, status TEXT DEFAULT 'committed', ts REAL, PRIMARY KEY(branch_id, effect_id));
CREATE TABLE embeddings( memory_id TEXT PRIMARY KEY, vec BLOB, dim INTEGER);
CREATE TABLE hints( id INTEGER PRIMARY KEY AUTOINCREMENT, session_ext TEXT, event TEXT, message_index INTEGER, ts REAL);
CREATE TABLE lint( id INTEGER PRIMARY KEY AUTOINCREMENT, branch_id TEXT, turn_index INTEGER, rule TEXT, severity TEXT, subjects TEXT, detail TEXT, evidence TEXT, ts REAL);
CREATE TABLE mechanic_settlement_receipts( branch_id TEXT, settlement_ref TEXT, turn_index INTEGER, contract_id TEXT, frame_ref TEXT, meaning_ref TEXT, outcome TEXT, outcome_quality TEXT, requirement_fingerprint TEXT, request_fingerprint TEXT, accepted_group_fingerprint TEXT, receipt_fingerprint TEXT, receipt_json TEXT, source TEXT, status TEXT DEFAULT 'committed', ts REAL, PRIMARY KEY(branch_id, settlement_ref));
CREATE TABLE memories( memory_id TEXT PRIMARY KEY, session_id TEXT, branch_id TEXT, tier TEXT, text TEXT, participants TEXT DEFAULT '[]', location_id TEXT, tags TEXT DEFAULT '[]', importance INTEGER DEFAULT 3, created_turn INTEGER, last_accessed_turn INTEGER DEFAULT 0, parent_id TEXT, scene_index INTEGER DEFAULT 0, embedding_ref INTEGER);
CREATE TABLE notes( session_id TEXT PRIMARY KEY, for_turn INTEGER, text TEXT, created REAL);
CREATE TABLE ops_journal( id INTEGER PRIMARY KEY AUTOINCREMENT, branch_id TEXT, turn_lo INTEGER, turn_hi INTEGER, ops TEXT, source TEXT, ts REAL);
CREATE TABLE player_lesson_intent_applications ( branch_id TEXT NOT NULL, turn_index INTEGER NOT NULL CHECK (turn_index >= 0), position INTEGER NOT NULL CHECK (position BETWEEN 0 AND 4), lesson_id TEXT NOT NULL, lesson_revision INTEGER NOT NULL CHECK (lesson_revision >= 1), lesson_fingerprint TEXT NOT NULL CHECK ( length(lesson_fingerprint) = 71 AND substr(lesson_fingerprint, 1, 7) = 'sha256:' AND substr(lesson_fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ), applied INTEGER NOT NULL CHECK (applied IN (0, 1)), reason TEXT NOT NULL CHECK ( reason IN ( 'exact_binding_applied', 'action_ambiguity_resolved', 'target_ambiguity_resolved', 'input_unambiguous', 'current_input_conflict', 'candidate_absent', 'candidate_ambiguous', 'lesson_conflict', 'explicit_multi_target', 'binding_failed' ) ), frame_id TEXT, selected_value TEXT, meaning_binding_ref TEXT, frame_fingerprint TEXT, applied_at REAL NOT NULL, PRIMARY KEY (branch_id, turn_index, position), UNIQUE (branch_id, turn_index, lesson_id), CHECK ( (applied = 1 AND reason IN ( 'exact_binding_applied', 'action_ambiguity_resolved', 'target_ambiguity_resolved' ) AND frame_id IS NOT NULL AND selected_value IS NOT NULL AND meaning_binding_ref IS NOT NULL AND length(meaning_binding_ref) = 71 AND substr(meaning_binding_ref, 1, 7) = 'sha256:' AND substr(meaning_binding_ref, 8) NOT GLOB '*[^0-9a-f]*' AND frame_fingerprint IS NOT NULL AND length(frame_fingerprint) = 71 AND substr(frame_fingerprint, 1, 7) = 'sha256:' AND substr(frame_fingerprint, 8) NOT GLOB '*[^0-9a-f]*') OR (applied = 0 AND reason NOT IN ( 'exact_binding_applied', 'action_ambiguity_resolved', 'target_ambiguity_resolved' ) AND selected_value IS NULL AND meaning_binding_ref IS NULL AND frame_fingerprint IS NULL) ) );
CREATE TABLE player_lesson_intent_receipts ( branch_id TEXT NOT NULL, turn_index INTEGER NOT NULL CHECK (turn_index >= 0), input_hash TEXT NOT NULL CHECK (length(input_hash) BETWEEN 1 AND 256), narration_mode TEXT NOT NULL CHECK ( narration_mode IN ('exploration', 'combat_opening', 'combat_exchange') ), frozen_selected_count INTEGER NOT NULL CHECK ( frozen_selected_count BETWEEN 0 AND 5 ), inherited_from_branch_id TEXT, selected_at REAL NOT NULL, PRIMARY KEY (branch_id, turn_index) );
CREATE TABLE player_lesson_intent_selection_items ( branch_id TEXT NOT NULL, turn_index INTEGER NOT NULL CHECK (turn_index >= 0), position INTEGER NOT NULL CHECK (position BETWEEN 0 AND 4), lesson_id TEXT NOT NULL, lesson_revision INTEGER NOT NULL CHECK (lesson_revision >= 1), lesson_fingerprint TEXT NOT NULL CHECK ( length(lesson_fingerprint) = 71 AND substr(lesson_fingerprint, 1, 7) = 'sha256:' AND substr(lesson_fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ), reason TEXT NOT NULL CHECK (reason = 'scope_and_exact_anchor_recognition'), scope TEXT NOT NULL CHECK ( scope IN ('every_rpg_turn', 'exploration', 'combat_opening', 'combat_exchange') ), anchor_entry_id TEXT NOT NULL, anchor_lex_id TEXT NOT NULL CHECK (anchor_lex_id IN ('action', 'referent')), anchor_concept_id TEXT NOT NULL CHECK (length(anchor_concept_id) BETWEEN 1 AND 128), anchor_meaning_fingerprint TEXT NOT NULL CHECK ( length(anchor_meaning_fingerprint) = 71 AND substr(anchor_meaning_fingerprint, 1, 7) = 'sha256:' AND substr(anchor_meaning_fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ), intent_slot TEXT NOT NULL CHECK (intent_slot IN ('action', 'target')), source_start INTEGER NOT NULL CHECK (source_start >= 0), source_end INTEGER NOT NULL CHECK (source_end > source_start), approval_source_id TEXT NOT NULL CHECK (length(approval_source_id) BETWEEN 1 AND 256), PRIMARY KEY (branch_id, turn_index, position), UNIQUE (branch_id, turn_index, lesson_id) );
CREATE TABLE player_lesson_selection_items ( branch_id TEXT NOT NULL, turn_index INTEGER NOT NULL CHECK (turn_index >= 0), position INTEGER NOT NULL CHECK (position BETWEEN 0 AND 4), lesson_id TEXT NOT NULL, lesson_revision INTEGER NOT NULL CHECK (lesson_revision >= 1), lesson_fingerprint TEXT NOT NULL CHECK ( length(lesson_fingerprint) = 71 AND substr(lesson_fingerprint, 1, 7) = 'sha256:' AND substr(lesson_fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ), reason TEXT NOT NULL CHECK (reason IN ('scope_match', 'scope_and_anchor_match')), scope TEXT NOT NULL CHECK ( scope IN ('every_rpg_turn', 'exploration', 'combat_opening', 'combat_exchange') ), anchor_entry_id TEXT, anchor_lex_id TEXT, anchor_concept_id TEXT, anchor_meaning_fingerprint TEXT, delivered INTEGER NOT NULL CHECK (delivered IN (0, 1)), delivered_at REAL, PRIMARY KEY (branch_id, turn_index, position), UNIQUE (branch_id, turn_index, lesson_id), CHECK ( (anchor_entry_id IS NULL AND anchor_lex_id IS NULL AND anchor_concept_id IS NULL AND anchor_meaning_fingerprint IS NULL) OR (anchor_entry_id IS NOT NULL AND anchor_lex_id IN ('capability', 'referent', 'scene', 'action') AND anchor_concept_id IS NOT NULL AND anchor_meaning_fingerprint IS NOT NULL AND length(anchor_meaning_fingerprint) = 71 AND substr(anchor_meaning_fingerprint, 1, 7) = 'sha256:' AND substr(anchor_meaning_fingerprint, 8) NOT GLOB '*[^0-9a-f]*') ), CHECK ( (delivered = 0 AND delivered_at IS NULL) OR (delivered = 1 AND delivered_at IS NOT NULL) ) );
CREATE TABLE player_lesson_selection_receipts ( branch_id TEXT NOT NULL, turn_index INTEGER NOT NULL CHECK (turn_index >= 0), input_hash TEXT NOT NULL CHECK (length(input_hash) BETWEEN 1 AND 256), narration_mode TEXT NOT NULL CHECK ( narration_mode IN ('exploration', 'combat_opening', 'combat_exchange') ), frozen_selected_count INTEGER NOT NULL CHECK ( frozen_selected_count BETWEEN 0 AND 5 ), inherited_from_branch_id TEXT, selected_at REAL NOT NULL, PRIMARY KEY (branch_id, turn_index) );
CREATE TABLE player_lessons ( lesson_id TEXT PRIMARY KEY NOT NULL CHECK ( length(lesson_id) = 39 AND substr(lesson_id, 1, 7) = 'lesson_' AND substr(lesson_id, 8) NOT GLOB '*[^0-9a-f]*' ), effect_type TEXT NOT NULL CHECK ( effect_type IN ('narration_behavior', 'intent_interpretation') ), title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120), scope TEXT NOT NULL CHECK ( scope IN ('every_rpg_turn', 'exploration', 'combat_opening', 'combat_exchange') ), do_text TEXT NOT NULL CHECK (length(do_text) <= 1000), avoid_text TEXT NOT NULL CHECK (length(avoid_text) <= 1000), anchor_entry_id TEXT, anchor_lex_id TEXT, anchor_concept_id TEXT, anchor_meaning_fingerprint TEXT, enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)), revision INTEGER NOT NULL CHECK (revision >= 1), fingerprint TEXT NOT NULL CHECK ( length(fingerprint) = 71 AND substr(fingerprint, 1, 7) = 'sha256:' AND substr(fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ), approved_via TEXT NOT NULL CHECK (approved_via = 'local_control_api'), approved_at REAL NOT NULL, created_at REAL NOT NULL, updated_at REAL NOT NULL, CHECK ( (effect_type = 'narration_behavior' AND (length(do_text) > 0 OR length(avoid_text) > 0)) OR (effect_type = 'intent_interpretation' AND length(do_text) > 0 AND length(avoid_text) > 0 AND anchor_entry_id IS NOT NULL AND anchor_lex_id IN ('action', 'referent')) ), CHECK ( (anchor_entry_id IS NULL AND anchor_lex_id IS NULL AND anchor_concept_id IS NULL AND anchor_meaning_fingerprint IS NULL) OR (anchor_entry_id IS NOT NULL AND anchor_lex_id IN ('capability', 'referent', 'scene', 'action') AND anchor_concept_id IS NOT NULL AND length(anchor_concept_id) BETWEEN 1 AND 128 AND anchor_meaning_fingerprint IS NOT NULL AND length(anchor_meaning_fingerprint) = 71 AND substr(anchor_meaning_fingerprint, 1, 7) = 'sha256:' AND substr(anchor_meaning_fingerprint, 8) NOT GLOB '*[^0-9a-f]*') ) );
CREATE TABLE playerlex_entries ( storage_token TEXT PRIMARY KEY NOT NULL CHECK ( length(storage_token) = 32 AND storage_token NOT GLOB '*[^0-9a-f]*' ), entry_id TEXT UNIQUE, schema TEXT NOT NULL CHECK (schema = 'playerlex-entry/2'), kind TEXT NOT NULL CHECK (kind IN ('name', 'alias', 'authoring_pattern')), surface TEXT NOT NULL, normalized_surface TEXT NOT NULL, lex_id TEXT NOT NULL CHECK (lex_id IN ('capability', 'referent', 'scene', 'action')), concept_id TEXT NOT NULL, meaning_fingerprint TEXT NOT NULL, approval_revision INTEGER NOT NULL CHECK (approval_revision >= 1), approved_at REAL NOT NULL, created_at REAL NOT NULL, updated_at REAL NOT NULL, record_json TEXT NOT NULL, UNIQUE (kind, normalized_surface, lex_id, concept_id), CHECK (length(surface) BETWEEN 1 AND 240), CHECK (length(normalized_surface) BETWEEN 1 AND 240), CHECK ( length(meaning_fingerprint) = 71 AND substr(meaning_fingerprint, 1, 7) = 'sha256:' AND substr(meaning_fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ) );
CREATE TABLE playerlex_retired_storage_tokens ( storage_token TEXT PRIMARY KEY NOT NULL CHECK ( length(storage_token) = 32 AND storage_token NOT GLOB '*[^0-9a-f]*' ) );
CREATE TABLE presets( preset_id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT, name TEXT, doc TEXT, created REAL, updated REAL, UNIQUE(kind, name));
CREATE TABLE recall( session_id TEXT PRIMARY KEY, for_turn INTEGER, lines TEXT, created REAL);
CREATE TABLE semantic_bootstrap_proofs( session_id TEXT PRIMARY KEY, branch_id TEXT UNIQUE, turn_index INTEGER, proof_fingerprint TEXT, post_ledger_hash TEXT, journal_high_water_after INTEGER, proof_json TEXT, committed_at REAL);
CREATE TABLE semantic_turn_attempts( lifecycle_key TEXT NOT NULL, attempt_index INTEGER NOT NULL, attempt_kind TEXT NOT NULL, request_hash TEXT NOT NULL, ledger_anchor_hash TEXT, status TEXT NOT NULL DEFAULT 'reserved', refusal_code TEXT, fallback_envelope_fingerprint TEXT, fallback_envelope_json TEXT, fallback_bytes BLOB, fallback_hash TEXT, terminal_envelope_fingerprint TEXT, terminal_envelope_json TEXT, accepted_bytes BLOB, accepted_hash TEXT, logical_message_id TEXT, selected_artifact_digest TEXT, created_at REAL NOT NULL, updated_at REAL NOT NULL, PRIMARY KEY(lifecycle_key, attempt_index), UNIQUE(lifecycle_key, request_hash) );
CREATE TABLE semantic_turn_delivery_claims( lifecycle_key TEXT NOT NULL, attempt_index INTEGER NOT NULL, logical_message_id TEXT NOT NULL, artifact_digest TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'claimed', claimed_at REAL NOT NULL, PRIMARY KEY(lifecycle_key, attempt_index) );
CREATE TABLE semantic_turn_delivery_completions( lifecycle_key TEXT NOT NULL, attempt_index INTEGER NOT NULL, logical_message_id TEXT NOT NULL, artifact_digest TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'completed', completed_at REAL NOT NULL, PRIMARY KEY(lifecycle_key, attempt_index) );
CREATE TABLE semantic_turn_lifecycles( lifecycle_key TEXT PRIMARY KEY, session_id TEXT NOT NULL, branch_id TEXT NOT NULL, turn_index INTEGER NOT NULL, accepted_prefix_pos INTEGER NOT NULL, accepted_head_hash TEXT NOT NULL, player_input_hash TEXT NOT NULL, semantic_contract_version TEXT NOT NULL, key_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'reserved', initial_request_hash TEXT NOT NULL, active_attempt_index INTEGER, base_envelope_fingerprint TEXT, terminal_envelope_fingerprint TEXT, pre_ledger_hash TEXT, mechanics_post_ledger_hash TEXT, post_ledger_hash TEXT, occurrence_fingerprint TEXT, effect_fingerprint TEXT, rng_fingerprint TEXT, config_fingerprint TEXT, engine_version TEXT, consumed_intent_id TEXT, next_intent_id TEXT, source_lifecycle_key TEXT, created_at REAL NOT NULL, updated_at REAL NOT NULL, UNIQUE(branch_id, turn_index) );
CREATE TABLE sessions( session_id TEXT PRIMARY KEY, external_id TEXT UNIQUE, anchor_hash TEXT, frontend TEXT DEFAULT 'unknown', active_branch TEXT, frozen INTEGER DEFAULT 0, created_at REAL, last_seen REAL, genesis TEXT DEFAULT '', mode TEXT DEFAULT 'enriched', label TEXT DEFAULT '', narrator_speaker TEXT DEFAULT '');
CREATE TABLE slices( session_id TEXT PRIMARY KEY, for_turn INTEGER, components TEXT, created REAL);
CREATE TABLE turn_texts( branch_id TEXT, turn_index INTEGER, user_text TEXT, assistant_text TEXT, PRIMARY KEY(branch_id, turn_index));
CREATE TABLE turns( branch_id TEXT, turn_index INTEGER, user_hash TEXT, assistant_hash TEXT, chain_hash TEXT, klass TEXT, gen_type TEXT, swipe_count INTEGER DEFAULT 0, settled INTEGER DEFAULT 0, extraction TEXT DEFAULT 'pending', PRIMARY KEY(branch_id, turn_index));
CREATE TABLE worldlex_capability_definitions ( world_id TEXT NOT NULL REFERENCES worldlex_world_lineages(world_id), definition_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision >= 1), fingerprint TEXT NOT NULL UNIQUE, parent_fingerprint TEXT, kind TEXT NOT NULL, owner_scope TEXT NOT NULL, owner_id TEXT NOT NULL, schema TEXT NOT NULL, compiler_version TEXT NOT NULL, record_json TEXT NOT NULL, created_at REAL NOT NULL, PRIMARY KEY (world_id, definition_id, revision), CHECK (schema = 'capability-definition/1'), CHECK (compiler_version = 'capability-compiler/1'), CHECK (kind IN ('skill', 'ability', 'spell', 'augment', 'cyberware', 'enemy_move')), CHECK (owner_scope IN ('world', 'actor', 'enemy_blueprint')), CHECK ( length(world_id) = 38 AND substr(world_id, 1, 6) = 'world_' AND substr(world_id, 7) NOT GLOB '*[^0-9a-f]*' ), CHECK ( length(fingerprint) = 71 AND substr(fingerprint, 1, 7) = 'sha256:' AND substr(fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ), CHECK ( parent_fingerprint IS NULL OR ( length(parent_fingerprint) = 71 AND substr(parent_fingerprint, 1, 7) = 'sha256:' AND substr(parent_fingerprint, 8) NOT GLOB '*[^0-9a-f]*' ) ) );
CREATE TABLE worldlex_world_lineages ( world_id TEXT PRIMARY KEY, parent_world_id TEXT REFERENCES worldlex_world_lineages(world_id), created_at REAL NOT NULL, CHECK ( length(world_id) = 38 AND substr(world_id, 1, 6) = 'world_' AND substr(world_id, 7) NOT GLOB '*[^0-9a-f]*' ), CHECK ( parent_world_id IS NULL OR ( length(parent_world_id) = 38 AND substr(parent_world_id, 1, 6) = 'world_' AND substr(parent_world_id, 7) NOT GLOB '*[^0-9a-f]*' AND parent_world_id <> world_id ) ) );
CREATE INDEX idx_director_branch ON director(branch_id, turn_index);
CREATE INDEX idx_effect_claim ON effect_receipts(branch_id, turn_index, family, target, direction, owner);
CREATE INDEX idx_lint_branch ON lint(branch_id, turn_index);
CREATE INDEX idx_mechanic_settlement_turn ON mechanic_settlement_receipts(branch_id, turn_index, contract_id);
CREATE INDEX idx_memories_branch ON memories(branch_id, parent_id);
CREATE UNIQUE INDEX idx_semantic_turn_consumed_intent ON semantic_turn_lifecycles(branch_id, consumed_intent_id) WHERE consumed_intent_id IS NOT NULL AND status='committed';
CREATE INDEX player_lesson_intent_application_lesson_idx ON player_lesson_intent_applications(lesson_id, branch_id, turn_index);
CREATE INDEX player_lesson_intent_receipt_lesson_idx ON player_lesson_intent_selection_items(lesson_id, branch_id, turn_index);
CREATE INDEX player_lesson_intent_receipt_time_idx ON player_lesson_intent_receipts(selected_at DESC, branch_id, turn_index);
CREATE INDEX player_lesson_receipt_lesson_idx ON player_lesson_selection_items(lesson_id, branch_id, turn_index);
CREATE INDEX player_lesson_receipt_time_idx ON player_lesson_selection_receipts(selected_at DESC, branch_id, turn_index);
CREATE INDEX playerlex_surface_idx ON playerlex_entries(normalized_surface, kind, lex_id, concept_id);
CREATE INDEX worldlex_definition_lineage_idx ON worldlex_capability_definitions(world_id, definition_id, revision DESC);
CREATE TRIGGER playerlex_reject_identity_replacement BEFORE INSERT ON playerlex_entries WHEN EXISTS ( SELECT 1 FROM playerlex_entries WHERE storage_token = NEW.storage_token ) OR ( NEW.entry_id IS NOT NULL AND EXISTS ( SELECT 1 FROM playerlex_entries WHERE entry_id = NEW.entry_id ) ) OR EXISTS ( SELECT 1 FROM playerlex_entries WHERE kind = NEW.kind AND normalized_surface = NEW.normalized_surface AND lex_id = NEW.lex_id AND concept_id = NEW.concept_id ) OR EXISTS ( SELECT 1 FROM playerlex_entries WHERE rowid = NEW.rowid ) BEGIN SELECT RAISE(ABORT, 'existing PlayerLex identity cannot be replaced'); END;
CREATE TRIGGER playerlex_reject_retired_storage_token BEFORE INSERT ON playerlex_entries WHEN EXISTS ( SELECT 1 FROM playerlex_retired_storage_tokens WHERE storage_token = NEW.storage_token ) BEGIN SELECT RAISE(ABORT, 'retired PlayerLex storage token'); END;
CREATE TRIGGER playerlex_reject_retired_storage_token_delete BEFORE DELETE ON playerlex_retired_storage_tokens BEGIN SELECT RAISE(ABORT, 'immutable PlayerLex retired storage token'); END;
CREATE TRIGGER playerlex_reject_retired_storage_token_replacement BEFORE INSERT ON playerlex_retired_storage_tokens WHEN EXISTS ( SELECT 1 FROM playerlex_retired_storage_tokens WHERE storage_token = NEW.storage_token ) OR EXISTS ( SELECT 1 FROM playerlex_retired_storage_tokens WHERE rowid = NEW.rowid ) BEGIN SELECT RAISE(ABORT, 'retired PlayerLex identity cannot be replaced'); END;
CREATE TRIGGER playerlex_reject_retired_storage_token_update BEFORE UPDATE ON playerlex_retired_storage_tokens BEGIN SELECT RAISE(ABORT, 'immutable PlayerLex retired storage token'); END;
CREATE TRIGGER playerlex_reject_storage_token_update BEFORE UPDATE OF storage_token ON playerlex_entries BEGIN SELECT RAISE(ABORT, 'immutable PlayerLex storage token'); END;
CREATE TRIGGER playerlex_retire_storage_token AFTER DELETE ON playerlex_entries BEGIN INSERT INTO playerlex_retired_storage_tokens(storage_token) VALUES(OLD.storage_token); END;
CREATE TRIGGER worldlex_definition_no_delete BEFORE DELETE ON worldlex_capability_definitions BEGIN SELECT RAISE(ABORT, 'WorldLex definition revisions are immutable'); END;
CREATE TRIGGER worldlex_definition_no_replacement BEFORE INSERT ON worldlex_capability_definitions WHEN EXISTS ( SELECT 1 FROM worldlex_capability_definitions WHERE fingerprint = NEW.fingerprint OR ( world_id = NEW.world_id AND definition_id = NEW.definition_id AND revision = NEW.revision ) ) BEGIN SELECT RAISE(ABORT, 'WorldLex definition revisions are immutable'); END;
CREATE TRIGGER worldlex_definition_no_update BEFORE UPDATE ON worldlex_capability_definitions BEGIN SELECT RAISE(ABORT, 'WorldLex definition revisions are immutable'); END;
CREATE TRIGGER worldlex_world_no_delete BEFORE DELETE ON worldlex_world_lineages BEGIN SELECT RAISE(ABORT, 'WorldLex world identities are immutable'); END;
CREATE TRIGGER worldlex_world_no_replacement BEFORE INSERT ON worldlex_world_lineages WHEN EXISTS ( SELECT 1 FROM worldlex_world_lineages WHERE world_id = NEW.world_id ) BEGIN SELECT RAISE(ABORT, 'WorldLex world identities are immutable'); END;
CREATE TRIGGER worldlex_world_no_update BEFORE UPDATE ON worldlex_world_lineages BEGIN SELECT RAISE(ABORT, 'WorldLex world identities are immutable'); END;
